package org.apache.commons.math3.optim;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.TooManyEvaluationsException;
import org.apache.commons.math3.exception.TooManyIterationsException;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;
import org.apache.commons.math3.util.Incrementor;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;

/**
 * Unit tests for BaseOptimizer constructor.
 * Since BaseOptimizer is protected and abstract, we use a concrete test subclass.
 */
public class BaseOptimizer_BaseOptimizer_TriageGen0Test {

    /**
     * Concrete implementation of BaseOptimizer for testing purposes.
     */
    private static class TestOptimizer extends BaseOptimizer {

        protected TestOptimizer(ConvergenceChecker<PAIR> checker) {
            super(checker);
        }

        @Override
        protected PAIR doOptimize() {
            return null;
        }
    }

    /**
     * Mock implementation of PAIR to satisfy generics.
     */
    private static class MockPair implements PAIR {
        @Override
        public double getPoint(int index) { return 0.0; }
        @Override
        public double getFunctionValue() { return 0.0; }
        @Override
        public double getGradient(int index) { return 0.0; }
    }

    @Test
    public void testConstructorAndGetters() {
        // Arrange
        @SuppressWarnings("unchecked")
        ConvergenceChecker<PAIR> mockChecker = mock(ConvergenceChecker.class);

        // Act
        TestOptimizer optimizer = new TestOptimizer(mockChecker);

        // Assert
        assertSame("ConvergenceChecker should be the same instance passed to constructor", 
            mockChecker, optimizer.getConvergenceChecker());

        // Verify initial states of incrementors via getters
        assertEquals("Initial evaluations should be 0", 0, optimizer.getEvaluations());
        assertEquals("Initial iterations should be 0", 0, optimizer.getIterations());
    }

    @Test
    public void testIncrementEvaluationCount() throws TooManyEvaluationsException {
        // Arrange
        @SuppressWarnings("unchecked")
        ConvergenceChecker<PAIR> mockChecker = mock(ConvergenceChecker.class);
        TestOptimizer optimizer = new TestOptimizer(mockChecker);

        // Act
        // Use reflection or access if possible, but here we test via the provided method signature logic
        // Note: incrementEvaluationCount is protected, accessible to the subclass
        invokeIncrementEvaluation(optimizer);

        // Assert
        assertEquals("Evaluations should increment to 1", 1, optimizer.getEvaluations());
    }

    @Test
    public void testIncrementIterationCount() throws TooManyIterationsException {
        // Arrange
        @SuppressWarnings("unchecked")
        ConvergenceChecker<PAIR> mockChecker = mock(ConvergenceChecker.class);
        TestOptimizer optimizer = new TestOptimizer(mockChecker);

        // Act
        invokeIncrementIteration(optimizer);

        // Assert
        assertEquals("Iterations should increment to 1", 1, optimizer.getIterations());
    }

    /**
     * Helper to call protected method incrementEvaluationCount via a wrapper in the test subclass 
     * or directly if we were inside the class. Since we are in a test class, 
     * we rely on the TestOptimizer subclass to expose it.
     */
    private void invokeIncrementEvaluation(TestOptimizer optimizer) throws TooManyEvaluationsException {
        optimizer.incrementEvaluationCount();
    }

    private void invokeIncrementIteration(TestOptimizer optimizer) throws TooManyIterationsException {
        optimizer.incrementIterationCount();
    }

    /**
     * Subclass to expose protected methods for testing
     */
    private static class TestOptimizerExposed extends TestOptimizer {
        protected TestOptimizerExposed(ConvergenceChecker<PAIR> checker) {
            super(checker);
        }

        @Override
        public void incrementEvaluationCount() throws TooManyEvaluationsException {
            super.incrementEvaluationCount();
        }

        @Override
        public void incrementIterationCount() throws TooManyIterationsException {
            super.incrementIterationCount();
        }
    }
}
